#define M_PI 3.1415926535897932384626433832795


// Return terrain height at texture position p
float terrain( in vec2 p)
{

    const float heightScale = 1.;
   	const bool flip = false;

    p = p*0.1;
    float scale = 1.0;
    //float scale = max(0.0, mix(1.0, 0.0, max(1.0, 2.0*max(abs(p.x), abs(p.y))) - 1.0));
    p = p+vec2(0.,1.);
    //scale = -2.0*scale*scale*scale + 3.0*scale*scale;
    if (p.x < -1.0 || p.x >= 1.0 || p.y < 0.0 || p.y >= 2.0)
        return 0.0;
   	p = mix(vec2(0.5, 0.0), vec2(1.0, 0.5), p);
    float val = texture( iChannel0, p, 0.0 ).x;
    if (flip)
        val = 1.0 - val;
   	//val = (val-0.5)*5.0;
	return val * scale * heightScale;
}

// Returns difference between height of point and terrain at that location
float map( in vec3 p )
{
    return p.y - terrain(p.xz);
}

vec3 calcNormal( in vec3 pos, float t )
{
	float e = 0.001;
	e = 0.0001*t;
    vec3  eps = vec3(e,0.0,0.0);
    vec3 nor;
    nor.x = map(pos+eps.xyy) - map(pos-eps.xyy);
    nor.y = map(pos+eps.yxy) - map(pos-eps.yxy);
    nor.z = map(pos+eps.yyx) - map(pos-eps.yyx);
    return normalize(nor);
}

// get height of ray intersection given origin and direction
float intersect( in vec3 ro, in vec3 rd )
{
    const float maxd = 40.0;
    const float precis = 0.001;
    float t = 0.0;
    for( int i=0; i<256; i++ )
    {
        float h = map( ro+rd*t );
        if( abs(h)<precis || t>maxd ) break;
        t += h*0.5;
    }
    return (t>maxd)?-1.0:t;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    bool showTexture = false;
    if (showTexture)
    {
        fragColor = vec4(texture( iChannel0, fragCoord, 0.0 ).xyz, 1.0);
        return;
    }

	float time = iTime;
    float rotTimeScale = 0.3;

    //vec4 m = iMouse / iResolution.xxxx;

    float mousePos = -iMouse.x/iResolution.x * 2.0 * M_PI * 8.0;
    time = mousePos;

	// Normal set up code for ray trace.
	vec2 xy = fragCoord.xy / iResolution.xy;
	vec2 s = (-1.0 + 2.0* xy) * vec2(iResolution.x/iResolution.y, 1.0);

    vec3 planeNormal = normalize(vec3(0.0, 1.0, 0.0));
    vec3 planeUp = abs(planeNormal.y) < 0.5
        ? vec3(0.0, 1.0, 0.0)
        : vec3(0.0, 0.0, 1.0);
   	vec3 planeSide = normalize(cross(planeNormal, planeUp));
    planeUp = cross(planeSide, planeNormal);

    float dist = 15.0;
    float height = 4.0;

    // ray origin
	vec3 ro = vec3(sin(time * rotTimeScale) * dist, height, cos(time * rotTimeScale) * dist);
    ro.y += (planeSide*ro.x + planeNormal*ro.y + planeUp*ro.z).y;
	vec3 cd = normalize(-ro);
	vec3 cu = vec3(0.0, 1.0, 0.0);
	vec3 cr = normalize(cross(cd, cu));
	cu = normalize(cross(cr, cd));

    // ray direction
	vec3 rd = normalize( s.x*cr + s.y*cu + 2.0*cd );

	vec3 col = vec3(0.7, 0.7, 0.7);

    vec3 sunDir = normalize(vec3(-1, -1, -1));
    vec3 ambientLight = vec3(0.3);
    vec3 sunLight = vec3(0.9);


    // transform ray
    ro = vec3(
        dot(ro, planeSide),
        dot(ro, planeNormal),
        dot(ro, planeUp)
    );
    rd = vec3(
        dot(rd, planeSide),
        dot(rd, planeNormal),
        dot(rd, planeUp)
    );

    const float maxd = 40.0;
    const float precis = 0.001;
    float t = 0.0;
    for( int i=0; i<256; i++ )
    {
        float h = map( ro+rd*t );
        if( abs(h)<precis || t>maxd ) break;
        t += h*0.5;
    }

    float intersection = (t>maxd)?-1.0:t;

    vec2 p = (ro+rd*t).xz;

    p = p*0.1;
    float scale = 1.0;
    //float scale = max(0.0, mix(1.0, 0.0, max(1.0, 2.0*max(abs(p.x), abs(p.y))) - 1.0));
    p = p+vec2(0.,1.);
    //scale = -2.0*scale*scale*scale + 3.0*scale*scale;
   	p = mix(vec2(0.5, 0.0), vec2(1.0, 0.5), p);
    vec3 texCol;

    if (p.x < 0. || p.x >= 1.0 || p.y < 0.0 || p.y >= 1.0)
        texCol = vec3(0.5);
    else
        // texCol = vec3(0.6);
        texCol = texture( iChannel1, p, 0.0 ).xyz;

    if(t > 0.0)
    {	
		// Get some information about our intersection
		vec3 pos = ro + t * rd;
		vec3 normal = calcNormal(pos, t);

        float shadow = intersect(pos, -sunDir) > 0.0 ? 0.0 : 1.0;

		vec2 uvp = vec2(dot(pos, planeSide), dot(pos, planeUp)) / 10.;

		// vec3 texCol = texture(iChannel1, uvp + vec2(.5, .5), 0.0).xyz;
        // vec3 texCol = texture(iChannel1, uvp + vec2(.5, .5), 0.0).xxx;

		col = texCol * clamp(-dot(normal, sunDir), 0.0f, 1.0f) * shadow * sunLight + ambientLight;

        float value = texture(iChannel0, uvp + vec2(.5, .5), 0.).x;
        // fragColor = vec4(value, value, value, 1);
	}

    // fragColor = vec4(t/10., t/10., t/10., 1.);
	fragColor = vec4(pow(col*1.2, vec3(2.2)), 1.0);
}

uint seed = 0x578437adU; // can be set to something else if you want a different set of random values

float baseLayer(vec2 position)
{
    return 5.0 + -5.0 * softClamp(worley(position, 2.0) * 1.0, 0.0, 0.8) * 2.0;
}

float mountainish(vec2 position)
{
    float scale = 2.0;
    float heightScale = 1.;

    position *= scale;
    // float frequency = 16.0;
    // float value = perlinNoise(position * frequency, seed); // single octave perlin noise
    // Range [0, 1]

    // Base layer is inverted worley noise with clamped valleys
    float ground = perlinNoise(position, .5, 1, 1., 1., seed) * 5.;

    float base = baseLayer(position);
    float slope = max(
        baseLayer(vec2(position.x-1., position.y)) - baseLayer(vec2(position.x+1., position.y)),
        baseLayer(vec2(position.x, position.y-1.)) - baseLayer(vec2(position.x, position.y+1.))
    );

    // Ridges and mountains with ridged perlin noise
    float midLayer = ridgedPerlinNoise(position, 3, 3, 0.8, 2.0, seed) * -0.5;// * slope;

    // Detail layer is perlin noisext
    // float baseLayer = 2.0 + -2.0 * ridgedPerlinNoise(position, 3, 1, 0.7, 2.0, seed); // multiple octaves
    float detailLayer = perlinNoise(position, 3., 5, 0.7, 2.0, seed) * 0.2;// * slope;


    float value = ground + base + midLayer + detailLayer;
    // float value = perlinNoise(position, 1, 6, 0.7, 2.0, seed);
    // float value = worley(position) * -1.0;
    value = (value + 1.0) * 0.5; // convert from range [-1, 1] to range [0, 1]
    return value * heightScale;
}


