/* PERLIN NOISE */

// implementation of MurmurHash (https://sites.google.com/site/murmurhash/) for a 
// single unsigned integer.

uint hash(uint x, uint seed) {
    const uint m = 0x5bd1e995U;
    uint hash = seed;
    // process input
    uint k = x;
    k *= m;
    k ^= k >> 24;
    k *= m;
    hash *= m;
    hash ^= k;
    // some final mixing
    hash ^= hash >> 13;
    hash *= m;
    hash ^= hash >> 15;
    return hash;
}

// implementation of MurmurHash (https://sites.google.com/site/murmurhash/) for a  
// 2-dimensional unsigned integer input vector.

uint hash(uvec2 x, uint seed){
    const uint m = 0x5bd1e995U;
    uint hash = seed;
    // process first vector element
    uint k = x.x; 
    k *= m;
    k ^= k >> 24;
    k *= m;
    hash *= m;
    hash ^= k;
    // process second vector element
    k = x.y; 
    k *= m;
    k ^= k >> 24;
    k *= m;
    hash *= m;
    hash ^= k;
	// some final mixing
    hash ^= hash >> 13;
    hash *= m;
    hash ^= hash >> 15;
    return hash;
}


vec2 gradientDirection(uint hash) {
    switch (int(hash) & 3) { // look at the last two bits to pick a gradient direction
    case 0:
        return vec2(1.0, 1.0);
    case 1:
        return vec2(-1.0, 1.0);
    case 2:
        return vec2(1.0, -1.0);
    case 3:
        return vec2(-1.0, -1.0);
    }
}

float interpolate(float value1, float value2, float value3, float value4, vec2 t) {
    return mix(mix(value1, value2, t.x), mix(value3, value4, t.x), t.y);
}

vec2 fade(vec2 t) {
    // 6t^5 - 15t^4 + 10t^3
	return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

float perlinNoise(vec2 position, uint seed) {
    vec2 floorPosition = floor(position);
    vec2 fractPosition = position - floorPosition;
    uvec2 cellCoordinates = uvec2(floorPosition);
    float value1 = dot(gradientDirection(hash(cellCoordinates, seed)), fractPosition);
    float value2 = dot(gradientDirection(hash((cellCoordinates + uvec2(1, 0)), seed)), fractPosition - vec2(1.0, 0.0));
    float value3 = dot(gradientDirection(hash((cellCoordinates + uvec2(0, 1)), seed)), fractPosition - vec2(0.0, 1.0));
    float value4 = dot(gradientDirection(hash((cellCoordinates + uvec2(1, 1)), seed)), fractPosition - vec2(1.0, 1.0));
    return interpolate(value1, value2, value3, value4, fade(fractPosition));
}

float perlinNoise(vec2 position, float frequency, int octaveCount, float persistence, float lacunarity, uint seed) {
    float value = 0.0;
    float amplitude = 1.0;
    float currentFrequency = frequency;
    uint currentSeed = seed;
    for (int i = 0; i < octaveCount; i++) {
        currentSeed = hash(currentSeed, 0x0U); // create a new seed for each octave
        value += perlinNoise(position * currentFrequency, currentSeed) * amplitude;
        amplitude *= persistence;
        currentFrequency *= lacunarity;
    }
    return value;
}

/* RIDGED PERLIN NOISE */

float ridgedPerlinNoise(vec2 position, int frequency, int octaveCount, float persistence, float lacunarity, uint seed) {
    float value = 0.0;
    float amplitude = 1.0;
    float currentFrequency = float(frequency);
    uint currentSeed = seed;
    for (int i = 0; i < octaveCount; i++) {
        currentSeed = hash(currentSeed, 0x0U); // create a new seed for each octave
        value += abs(perlinNoise(position * currentFrequency, currentSeed) * amplitude);
        amplitude *= persistence;
        currentFrequency *= lacunarity;
    }
    return value;
}

/* WORLEY NOISE */


// Determines how many cells there are
#define NUM_CELLS 2.0

// Arbitrary random, can be replaced with a function of your choice
float rand(vec2 co){
    return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
}

// Returns the point in a given cell
vec2 get_cell_point(ivec2 cell, float num_cells) {
	vec2 cell_base = vec2(cell) / num_cells;
	float noise_x = rand(vec2(cell));
    float noise_y = rand(vec2(cell.yx));
    return cell_base + (0.5 + 1.5 * vec2(noise_x, noise_y)) / num_cells;
}

// Performs worley noise by checking all adjacent cells
// and comparing the distance to their points
float worley(vec2 coord, float num_cells) {
    ivec2 cell = ivec2(coord * num_cells);
    float dist = 1.0;

    // Search in the surrounding 5x5 cell block
    for (int x = 0; x < 5; x++) { 
        for (int y = 0; y < 5; y++) {
        	vec2 cell_point = get_cell_point(cell + ivec2(x-2, y-2), num_cells);
            dist = min(dist, distance(cell_point, coord));

        }
    }

    dist /= length(vec2(1.0 / num_cells));
    dist = 1.0 - dist;
    return dist;
}

float softClamp(float x, float a, float b)
{
    return smoothstep(0., 1., (2./3.)*(x - a)/(b - a) + (1./6.))*(b - a) + a;
}

uint seed = 0x578437adU; // can be set to something else if you want a different set of random values

float baseLayer(vec2 position)
{
    return 5.0 + -5.0 * softClamp(worley(position, 2.0) * 1.0, 0.0, 0.8) * 2.0;
}

float mountainish(vec2 position)
{
    float scale = 2.0;
    float heightScale = 0.5;

    position *= scale;
    // float frequency = 16.0;
    // float value = perlinNoise(position * frequency, seed); // single octave perlin noise
    // Range [0, 1]

    float ground = perlinNoise(position, .5, 1, 1., 1., seed) * 5.;

    // Base layer is inverted worley noise with clamped valleys
    float base = baseLayer(position);
    float slope = sqrt(
        pow(baseLayer(vec2(position.x-1., position.y)) - baseLayer(vec2(position.x+1., position.y)), 2.) +
        pow(baseLayer(vec2(position.x, position.y-1.)) - baseLayer(vec2(position.x, position.y+1.)), 2.)
    );

    // Ridges and mountains with ridged perlin noise
    float midLayer = ridgedPerlinNoise(position, 3, 3, 0.8, 2.0, seed) * -0.5 * slope;

    // Detail layer is perlin noisext
    // float baseLayer = 2.0 + -2.0 * ridgedPerlinNoise(position, 3, 1, 0.7, 2.0, seed); // multiple octaves
    float detailLayer = perlinNoise(position, 3., 5, 0.7, 2.0, seed) * 0.2 * slope;


    float value = ground + base + midLayer + detailLayer;
    // float value = perlinNoise(position, 1, 6, 0.7, 2.0, seed);
    // float value = worley(position) * -1.0;
    value = (value + 1.0) * 0.5; // convert from range [-1, 1] to range [0, 1]
    return value * heightScale;
}

vec3 mountainColors(vec2 position, bool debug)
{
    float value = mountainish(position);
    vec3 highCol = vec3(0.9, .9, .9);
    vec3 lowCol = vec3(.5, .5, .5);
    return lowCol * (1. - value) + highCol * value;
}


